    private static Descriptor[] concat(Descriptor[]... parts) {
        int total = 0;
        for (Descriptor[] part : parts) total += part.length;
        Descriptor[] all = new Descriptor[total];
        int offset = 0;
        for (Descriptor[] part : parts) {
            System.arraycopy(part, 0, all, offset, part.length);
            offset += part.length;
        }
        return all;
    }
